import {fleetTechnologyControls} from './technology-actions.js';
import {helpTip,fortificationHelp,paranoiaHelp} from './help-tips.js';
import {escapeHtml as h,number} from './domain.js';
import {planetArt,badge,civilizationBadge,shipArt} from './art.js';
export const shipTypes={scout:{name:'Scout',cost:2000,hours:2,capacity:0,description:'Reconnaissance · combat spatial léger'},bomber:{name:'Bombardier',cost:12000,hours:8,capacity:10,description:'Appui au sol · transport de troupes'},fighter:{name:'Destroyer',cost:16000,hours:10,capacity:10,description:'Supériorité spatiale · transport de troupes'}};
const money=v=>number(v)+' Þ';
const decimal=v=>new Intl.NumberFormat('fr-FR',{maximumFractionDigits:2}).format(Number(v)||0);
const date=v=>new Intl.DateTimeFormat('fr-FR',{dateStyle:'short',timeStyle:'short'}).format(new Date(v));
const errorBox='<p class="form-error" role="alert" hidden></p>';
const input=(name,label,max,value=0)=>`<label>${label}<input type="number" name="${name}" min="0" max="${max}" value="${value}" step="1" required></label>`;

export function militaryDestinations(signals,originId,query=''){
 const origin=signals.find(p=>p.id===originId);if(!origin)return [];
 const term=query.trim().toLocaleLowerCase('fr');
 return signals.filter(p=>p.id!==originId&&(!term||p.designation.toLocaleLowerCase('fr').includes(term))).map(p=>({...p,distance:Math.hypot(p.x-origin.x,p.y-origin.y)})).sort((a,b)=>term?(Number(b.designation.toLocaleLowerCase('fr')===term)-Number(a.designation.toLocaleLowerCase('fr')===term)||a.distance-b.distance):a.distance-b.distance).slice(0,15);
}
export function travelSeconds(distance){return Math.ceil((3600+Math.min(Math.sqrt(2000000),Math.max(0,distance))/Math.sqrt(2000000)*601200)/2);}
export function timeLeft(at,now=Date.now()){
 const seconds=Math.max(0,Math.ceil((new Date(at).getTime()-now)/1000));if(!seconds)return 'Arrivée à confirmer';const hours=Math.floor(seconds/3600),minutes=Math.floor(seconds%3600/60);return hours>=24?`${Math.floor(hours/24)} j ${hours%24} h`:`${hours} h ${String(minutes).padStart(2,'0')} min`;
}
const countdown=at=>`<time datetime="${h(at)}" data-countdown="${h(at)}">${timeLeft(at)}</time>`;
const stanceName=p=>p.stance==='attack'?'En attaque':p.stance==='mixed'?'Attaque & défense':p.is_own?'Monde contrôlé':'En défense';
const stanceClass=p=>p.stance==='attack'||p.stance==='mixed'?'stance-attack':p.is_own?'stance-own':'stance-defend';
const population=n=>new Intl.NumberFormat('en',{notation:'compact',maximumFractionDigits:1}).format(Number(n)||0);
function routeIdentity(f){
 const endpoint=(name,appearance)=>`<span class="route-endpoint">${planetArt(appearance,true)?`<img src="${planetArt(appearance,true)}" alt="" width="32" height="32">`:''}<span>${h(name||'Destination')}</span></span>`;
 return `<span class="route-identity">${endpoint(f.origin,f.origin_appearance)}<span aria-hidden="true">→</span>${endpoint(f.destination,f.destination_appearance)}</span>`;
}
function militaryLocationHeader(p,worlds,owned){return `<section class="military-world ${stanceClass(p)}"><img src="${planetArt(p.appearance||p.race+'_'+p.resource)}" alt="" width="150" height="150"><div><span class="eyebrow">${h(stanceName(p))}</span><label class="field">Planète<select id="military-world" class="${stanceClass(p)}">${worlds.map(w=>`<option class="${stanceClass(w)}" style="color:${w.stance==='attack'||w.stance==='mixed'?'#f19b98':w.is_own?'#d6dfe8':'#91ddbb'}" value="${h(w.id)}" ${w.id===p.id?'selected':''}>${h(w.name)}${w.is_own?'':` · ${stanceName(w)}`}</option>`).join('')}</select></label><div class="military-traits">${badge('race',p.race)}${badge('resource',p.resource)}${civilizationBadge()}<b>${p.civilization}</b><span class="world-population">${population(p.population)}</span></div></div>${owned?`<div class="recruitment-status"><strong>${decimal(owned.daily_recruits)}</strong><span>soldats / jour</span><small>${number(owned.soldiers)} en garnison${owned.contested?' · recrutement suspendu':''}</small><form data-military="recruitment" data-planet="${h(p.id)}"><input type="hidden" name="enabled" value="${!owned.recruitment_enabled}"><button class="recruitment-toggle ${owned.recruitment_enabled?'enabled':''}" type="submit" aria-pressed="${owned.recruitment_enabled}"><i></i>${owned.recruitment_enabled?'Recrutement actif':'Recrutement arrêté'}</button>${errorBox}</form></div>`:`<div class="foreign-location-status"><strong>${h(stanceName(p))}</strong><span>Position extérieure</span></div>`}</section>`;}
function totalUnits(t,race){return `<div class="reserves-grid total-units">${[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']].map(([key,label])=>`<div>${key==='soldiers'?badge('race',race,'troop-symbol'):shipArt(race,key==='scouts'?'scout':key==='bombers'?'bomber':'fighter')}<span>${label}<strong>${number(t[key]||0)}</strong></span></div>`).join('')}</div>`;}
function localForceSummary(p){
 const t=p.own_totals||{...p,soldiers:p.soldiers||0,ground:p.soldiers||0,embarked:0,fleets:0},ownRaces=[...new Set((p.forces||[]).filter(f=>f.is_own).map(f=>f.race))],race=ownRaces.length===1?ownRaces[0]:p.race;
 return `<section class="planet-reserves total-forces"><div class="reserves-heading"><span class="eyebrow">TOTAL DE VOS FORCES PRÉSENTES</span><strong>${number(t.fleets||0)} flotte${Number(t.fleets)>1?'s':''} constituée${Number(t.fleets)>1?'s':''}</strong></div>${totalUnits(t,race)}<p class="forces-breakdown">${number(t.ground||0)} soldats au sol <span>·</span> ${number(t.embarked||0)} embarqués <span>·</span> Réserves et flottes comprises</p></section>`;
}
function foreignForcesView(p){
 const forces=(p.forces||[]).filter(f=>!f.is_own);if(!forces.length)return '';
 return `<section class="foreign-forces"><div class="military-section-heading"><div><span class="eyebrow">PRÉSENCES SUR CE MONDE</span><h2>Forces étrangères</h2></div></div><div class="force-camps">${['defend','attack'].map(side=>{const rows=forces.filter(f=>f.mission===side);return rows.length?`<section class="force-camp ${side==='attack'?'stance-attack':'stance-defend'}"><h3>${side==='attack'?'En attaque':'En défense'}</h3>${rows.map(f=>`<article class="observed-force"><header>${badge('race',f.race)}<b>${h(f.name)}</b>${new Date(f.unavailable_until)>new Date()||new Date(f.ground_ready_at)>new Date()?'<span class="na-status">N/A</span>':''}</header>${fleetUnits(f)}</article>`).join('')}</section>`:'';}).join('')}</div></section>`;
}
function fleetUnits(f){return `<div class="fleet-units"><span>${shipArt(f.race,'scout')}<b>${number(f.scouts)}</b> scouts</span><span>${shipArt(f.race,'bomber')}<b>${number(f.bombers)}</b> bombardiers</span><span>${shipArt(f.race,'fighter')}<b>${number(f.fighters)}</b> destroyers</span><span>${badge('race',f.race)}<b>${number(f.soldiers)}</b> embarqués</span><span>${badge('race',f.race)}<b>${number(f.ground_soldiers)}</b> au sol</span></div>`;}
function fleetPanel(f,technology){
 const capacity=10*(f.bombers+f.fighters),moving=f.status==='transit',locked=new Date(f.unavailable_until)>new Date(),groundLocked=new Date(f.ground_ready_at)>new Date();
 return `<article class="fleet-row"><div class="fleet-heading"><div><span class="eyebrow">${moving?'EN TRANSIT':f.mission==='attack'?'POSITION OFFENSIVE':'POSITION DÉFENSIVE'}</span><h3>${h(f.name)}</h3><p>${moving?routeIdentity(f):h(f.location)}</p></div><div class="fleet-status">${moving?countdown(f.arrives_at):locked||groundLocked?`<span class="na-status">N/A ${Math.max(1,Math.ceil((Math.max(new Date(f.unavailable_until).getTime()||0,new Date(f.ground_ready_at).getTime()||0)-Date.now())/3600000))}</span> · ${date(locked?f.unavailable_until:f.ground_ready_at)}`:'Stationnée'}</div></div>${fleetUnits(f)}${moving?`<button class="secondary" data-mission-fleet="${h(f.id)}">Changer de destination →</button>`:`<div class="fleet-actions" ${locked?'inert':''}><form data-military="load" data-fleet="${h(f.id)}" class="load-troops">${input('soldiers','Soldats embarqués',capacity,f.soldiers)}<span class="transport-capacity">/ ${capacity}</span><button type="submit" class="secondary">Charger / décharger</button>${errorBox}</form>${f.scouts+f.bombers+f.fighters?`<button class="secondary" data-mission-fleet="${h(f.id)}">Donner un ordre →</button>`:''}<form data-military="mission" data-fleet="${h(f.id)}"><input name="mission" type="hidden" value="${f.mission==='attack'?'defend':'attack'}"><button class="secondary" type="submit">Passer en ${f.mission==='attack'?'défense':'attaque'}</button>${errorBox}</form>${f.own_location?`<form data-military="disband" data-fleet="${h(f.id)}"><button class="text-button" type="submit">Rendre les unités à la planète</button>${errorBox}</form>`:''}</div>`}${fleetTechnologyControls(f,technology)}</article>`;
}
export function militaryView(data,selectedId,pending){
 if(!data)return '<p class="empty">Établissement des communications militaires…</p>';
 const worlds=data.locations||data.planets.map(p=>({...p,is_own:true,stance:'own'})),location=worlds.find(p=>p.id===selectedId)||worlds[0],p=data.planets.find(p=>p.id===location?.id),available=p?.available_soldiers??p?.soldiers??0,localFleets=data.fleets.filter(f=>f.status==='stationed'&&f.planet_id===location?.id&&Number(f.scouts)+Number(f.bombers)+Number(f.fighters)+Number(f.soldiers)+Number(f.ground_soldiers)>0);
 return `<div class="military-page">${pending?`<div class="military-pending"><p>Un ordre attend sa confirmation.</p><button class="secondary" id="retry-military">Reprendre cet ordre</button></div>`:''}${data.debt>0?'<p class="form-error">Entretien à régulariser : les nouveaux achats sont suspendus.</p>':''}${location?militaryLocationHeader(location,worlds,p)+localForceSummary(location):''}${p?`
 <form class="planet-paranoia" data-military="paranoid" data-planet="${h(p.id)}"><input type="hidden" name="enabled" value="${!p.paranoid}"><span>Fortification (${Math.round((p.fortification||0)*100)} %) ${helpTip('fortification-tip','Fonctionnement de la fortification',fortificationHelp)}${p.contested?' · Contrôle contesté':''}${p.blockaded?' · Blocus commercial':''}</span><button class="secondary" type="submit">Mode paranoïaque : ${p.paranoid?'activé':'désactivé'}</button>${helpTip('paranoia-tip','Fonctionnement du mode paranoïaque',paranoiaHelp,true)}${errorBox}</form><section class="planet-reserves" aria-label="Forces disponibles sur la planète"><div class="reserves-heading"><span class="eyebrow">DISPONIBLES SUR LA PLANÈTE</span><small>Unités hors des flottes constituées</small></div><div class="reserves-grid">${[['soldiers','Soldats'],['scouts','Scouts'],['bombers','Bombardiers'],['fighters','Destroyers']].map(([key,label])=>`<div>${key==='soldiers'?badge('race',p.race,'troop-symbol'):shipArt(p.race,key==='scouts'?'scout':key==='bombers'?'bomber':'fighter')}<span>${label}<strong>${number(p[key])}</strong></span></div>`).join('')}</div></section>
 <section class="shipyard"><div class="military-section-heading"><div><span class="eyebrow">INDUSTRIE ORBITALE</span><h2>Chantiers spatiaux</h2></div><span><b>${p.factories-p.busy_factories}</b> / ${p.factories} usines libres</span><form data-military="factory" data-planet="${h(p.id)}" data-expected-factories="${p.factories}"><button class="secondary" type="submit" ${data.jobs.some(j=>j.planet_id===p.id&&j.kind==='factory')||p.factories>=200?'disabled':''}>Construire une usine · ${money(p.factory_price)} · ${decimal(p.factory_hours)} h</button>${errorBox}</form></div><div class="ship-production">${Object.entries(shipTypes).map(([kind,s])=>`<article>${shipArt(p.race,kind)}<div><h3>${s.name}</h3><p>${s.description}</p><small>${money(s.cost)} · ${decimal(s.hours/(p.resource==='ferros'?1.15:1))} h</small></div><form data-military="ship" data-planet="${h(p.id)}"><input type="hidden" name="kind" value="${kind}"><label class="visually-hidden" for="ship-${kind}">Nombre de ${s.name.toLowerCase()}s</label><input id="ship-${kind}" name="quantity" type="number" min="1" max="${Math.max(1,p.factories-p.busy_factories)}" value="1" required><button class="secondary" type="submit" ${p.factories===p.busy_factories?'disabled':''}>Produire</button>${errorBox}</form></article>`).join('')}</div>${data.jobs.filter(j=>j.planet_id===p.id).length?`<ol class="military-jobs">${data.jobs.filter(j=>j.planet_id===p.id).map(j=>`<li><span>${j.kind==='factory'?'Nouvelle usine':shipTypes[j.kind].name}</span><div class="build-progress"><i style="width:${Math.max(0,Math.min(100,(new Date(data.server_now)-new Date(j.started_at))/(new Date(j.finishes_at)-new Date(j.started_at))*100))}%"></i></div>${j.paused_at?'<span class="na-status">Suspendu · contrôle contesté</span>':countdown(j.finishes_at)}</li>`).join('')}</ol>`:''}</section>
 <section class="assemble-fleet"><div><span class="eyebrow">UNITÉS EN RÉSERVE</span><h2>Constituer une flotte</h2></div><form data-military="assemble" data-planet="${h(p.id)}" data-soldiers-available="${available}"><label class="fleet-name-field">Nom de la flotte<input name="name" maxlength="40" minlength="1" value="Flotte de ${h(p.name.slice(0,25))}" required></label>${[['scouts','Scouts',p.scouts],['bombers','Bombardiers',p.bombers],['fighters','Destroyers',p.fighters],['soldiers','Soldats à embarquer',available]].map(([key,label,stock])=>`<label>${label}<small>${number(stock)} disponibles</small><input type="number" name="${key}" min="0" max="${key==='soldiers'?0:stock}" value="0" step="1" required></label>`).join('')}<div class="assembly-transport" aria-live="polite"><span>Transport de soldats</span><output data-assembly-transport>0 / 0 places occupées</output><small data-assembly-remaining>${number(available)} soldats restent sur la planète</small></div><button class="secondary" type="submit" disabled>Constituer la flotte →</button>${errorBox}</form></section>`:location?'':'<p class="empty">Aucune force stationnée. Vos déplacements sont accessibles dans Flottes en transit.</p>'}
 ${location?foreignForcesView(location):''}<section class="fleet-roster"><div class="military-section-heading"><div><span class="eyebrow">FORCES EXPÉDITIONNAIRES</span><h2>Vos flottes</h2></div><span>${localFleets.length} détachement${localFleets.length>1?'s':''} ici</span></div>${localFleets.length?localFleets.map(f=>fleetPanel(f,data.technology)).join(''):'<p class="empty">Aucune de vos flottes constituées sur cette planète.</p>'}</section><section id="mission-orders" class="mission-orders" hidden></section></div>`;
}
export function missionView(fleet,signals){return `<div class="military-section-heading"><h2>Ordre de mission · ${h(fleet.name)}</h2><button class="text-button" id="close-mission">Fermer</button></div><form data-military="${fleet.status==='transit'?'redirect':'dispatch'}" data-fleet="${h(fleet.id)}"><label class="field">Rechercher une planète<input id="mission-search" type="search" placeholder="Nom de la planète" autocomplete="off"></label><label class="field">Destination<select name="target_id" id="mission-destination" required></select></label><p id="mission-eta" class="form-note"></p>${fleet.status==='transit'?'':`<label class="field">Mission<select name="mission"><option value="defend">Défense / renfort</option><option value="attack">Attaque</option></select></label>`}<button class="primary" type="submit">${fleet.status==='transit'?'Modifier la trajectoire':'Envoyer la flotte'} →</button>${errorBox}</form>`;}
export function bindMissionDestinations(root,signals,originId,position=null){
 if(position)signals=[...signals.filter(p=>p.id!==originId),{id:originId||'in-flight',designation:'Position en vol',...position}];if(position&&!originId)originId='in-flight';
 const search=root.querySelector('#mission-search'),select=root.querySelector('#mission-destination'),eta=root.querySelector('#mission-eta');let choices=[];
 const updateETA=()=>{const target=choices.find(p=>p.id===select.value);eta.textContent=target?`Distance ${decimal(target.distance/50)} · voyage ${timeLeft(new Date(Date.now()+travelSeconds(target.distance)*1000))}`:'Aucune destination correspondante.';};
 const update=()=>{choices=militaryDestinations(signals,originId,search.value);select.innerHTML=choices.map(p=>`<option value="${h(p.id)}">${h(p.designation)}${p.clan_name?` [${h(p.clan_name)}]`:''}</option>`).join('');updateETA();};search.addEventListener('input',update);select.addEventListener('change',updateETA);update();
}
export function foreignPresenceView(data){const presence=data?.presence||[];return presence.length?`<section class="foreign-presence"><div class="military-section-heading"><div><span class="eyebrow">PRÉSENCE EXTÉRIEURE</span><h2>Vos forces sur d’autres mondes</h2></div></div>${presence.map(p=>`<button class="foreign-world" data-page="fleets" data-military-location="${h(p.id)}"><img src="${planetArt(p.appearance,true)}" alt="" width="52" height="52"><span><b>${h(p.name)}</b><small>${p.attacking?'En attaque':'En défense'}</small></span><span>${number(p.ships)} vaisseaux · ${number(p.soldiers)} au sol · ${number(p.embarked)} embarqués</span><span>Gérer →</span></button>`).join('')}</section>`:'';}
export function militaryCommandView(data){
 if(!data)return '';
 const moving=data.fleets.filter(f=>f.status==='transit'),foreign=(data.locations||[]).filter(p=>!p.is_own);
 return `<div class="command-operations"><section><div class="military-section-heading"><h2>Flottes en transit</h2><button class="text-button" data-page="transit">Tout voir →</button></div>${moving.length?moving.slice(0,4).map(f=>`<article class="command-transit"><header><b>${h(f.name)}</b>${countdown(f.arrives_at)}</header>${routeIdentity(f)}<small>${number(Number(f.scouts)+Number(f.bombers)+Number(f.fighters))} vaisseaux · ${number(f.soldiers)} soldats</small></article>`).join(''):'<p class="empty">Aucune flotte en vol.</p>'}</section><section><div class="military-section-heading"><h2>Positions extérieures</h2></div>${foreign.length?foreign.map(p=>`<button class="command-position ${stanceClass(p)}" data-page="fleets" data-military-location="${h(p.id)}"><img class="position-planet" src="${planetArt(p.appearance,true)}" alt="" width="56" height="56"><span><b>${h(p.name)}</b><strong>${h(stanceName(p))}</strong><span class="position-traits">${badge('race',p.race)}${badge('resource',p.resource)}${civilizationBadge()} ${p.civilization} <span>· ${population(p.population)}</span></span><small><span class="defense-text">Défense : ${number(p.defense.fleets)} flotte${Number(p.defense.fleets)>1?'s':''} · ${number(p.defense.ships)} vaisseaux · ${number(p.defense.soldiers)} soldats</span><span class="attack-text">Attaque : ${number(p.attack.fleets)} flotte${Number(p.attack.fleets)>1?'s':''} · ${number(p.attack.ships)} vaisseaux · ${number(p.attack.soldiers)} soldats</span></small></span></button>`).join(''):'<p class="empty">Aucune force sur un monde étranger.</p>'}</section></div>`;
}
export {battleReportsView} from './reports.js';
export const militaryHelp=`<h3>Armées, chantiers et expéditions</h3><p>Le recrutement progresse chaque heure, avec fractions conservées. Base alpha : 1,5 soldat par jour × population en millions × civilisation. Conseil multiplie par 0,8, Tyrannie par 1,2, Biomasse par 1,15. La garnison recrute jusqu’à un soldat pour 1 000 habitants ; désactiver le recrutement conserve la fraction acquise. Les mondes neutres ne recrutent pas.</p><p>Chaque monde commence avec cinq usines. Une usine produit un vaisseau à la fois. Scouts : 2 000 Þ / 2 h ; bombardiers : 12 000 Þ / 8 h ; destroyers : 16 000 Þ / 10 h. Ferros divise ces durées par 1,15. La sixième usine coûte 25 000 Þ et prend 24 h ; prix du rang n : 25 000 × (n/6)^1,6, durée : 24 × [1 + 0,08 × (n − 6)] h, avant Ferros. Un seul chantier d’usine par planète, jusqu’à 200 usines.</p><p>Constituez une flotte avec vos vaisseaux disponibles puis chargez les soldats. Scouts sans transport ; chaque bombardier ou destroyer embarque dix soldats. Le trajet conserve l’entretien, et ses unités sont immédiatement retirées de leur origine. Une traversée diagonale complète prend trois jours et demi ; chaque voyage prend trente minutes plus sa part de distance. La destination peut changer en vol depuis la position atteinte. Les soldats débarquent au premier combat horaire situé au moins une heure après l’arrivée. Une flotte doit attendre une heure après son arrivée avant de charger, débarquer ou repartir. Elle peut ensuite repartir en laissant ses troupes au sol, ou les réembarquer avec des transports présents.</p><p>Les vaisseaux en réserve et les flottes constituées stationnées combattent ensemble selon leur mission. Les soldats embarqués attendent leur débarquement avant de participer au sol. Les missions défensives combattent ensemble contre les missions offensives, elles aussi regroupées. Proposition alpha active : scout puissance spatiale 1 / résistance 2 ; destroyer 8 / 12 ; bombardier 0 / 10 et frappe au sol de 2 par heure. Soldat puissance et résistance 1. Chaque heure, les dégâts spatiaux et terrestres sont simultanés : 60 % de la puissance spatiale opposée et 4 % au sol, répartis proportionnellement, avec fractions conservées. Les bombardiers soutiennent le sol seulement avec une puissance spatiale au moins triple de celle des défenseurs. Avec 100 vaisseaux offensifs et cette maîtrise spatiale, le commerce est bloqué aux deux extrémités de chaque liaison ; il reprend deux heures après la levée. Les bombardiers ne tirent pas sur les vaisseaux ; les destroyers ne bombardent pas. Les bonus de race suivent l’origine des unités. La perte des transports entraîne celle de leurs passagers à proportion.</p><p>Après élimination des défenseurs disponibles au sol, les attaquants ayant des soldats débarqués prennent la planète. Le groupe ayant le plus de soldats désigne le conquérant ; égalité départagée de façon stable. Plafond : douze mondes. Les usines, la race et la ressource sont conservées ; les constructions inachevées sont interrompues, avec remboursement au précédent propriétaire pour les vaisseaux et usines, mais sans remboursement pour les investissements de civilisation. Les forces offensives survivantes passent en défense. Un renommage est disponible après capture. Les nouveaux rapports distinguent vos forces, les forces alliées et ennemies, avant et après le combat, avec leurs pertes. Les anciens rapports peuvent contenir des données partielles. La supériorité numérique au sol suspend recrutement et industrie, et interdit la fermeture ou la réduction des liaisons. Le mode paranoïaque force les renforts sans clan commun à attaquer à leur arrivée. Changer de camp impose N/A 1 ; passer en défense ajoute une heure, jusqu’à N/A 4. Les armées N/A subissent les tirs mais ne combattent pas, ne se déplacent pas et ne comptent pas pour une conquête. Toute conquête ajoute une heure N/A aux forces présentes. Les fortifications commencent après sept jours, atteignent +60 % à deux mois puis +95 % à cinq mois ; une conquête militaire les remet à zéro. Ces valeurs sont un équilibrage provisoire pour l’alpha.</p>`;

export function assemblyQuote(values,available){
 const counts=['scouts','bombers','fighters','soldiers'].map(key=>Number(values[key]));
 if(counts.some(n=>!Number.isSafeInteger(n)||n<0))return null;
 const [scouts,bombers,fighters,soldiers]=counts,capacity=10*(bombers+fighters);
 return {capacity,limit:Math.min(available,safeCapacity(capacity)),remaining:available-soldiers,valid:scouts+bombers+fighters>0&&soldiers<=capacity&&soldiers<=available};
}
const safeCapacity=value=>Number.isSafeInteger(value)?value:0;
export function bindAssembly(root){root.querySelectorAll('form[data-military="assemble"]').forEach(form=>{
 const update=()=>{const values=Object.fromEntries(new FormData(form)),quote=assemblyQuote(values,Number(form.dataset.soldiersAvailable));
  form.elements.soldiers.max=String(quote?.limit||0);
  form.querySelector('[data-assembly-transport]').textContent=quote?`${number(Number(values.soldiers))} / ${number(quote.capacity)} places occupées`:'Composition invalide';
  form.querySelector('[data-assembly-remaining]').textContent=quote&&quote.remaining>=0?`${number(quote.remaining)} soldats restent sur la planète`:'Soldats disponibles insuffisants';
  form.querySelector('button[type=submit]').disabled=!quote?.valid||!form.checkValidity();
 };form.addEventListener('input',update);update();
});}

export function commercialNotificationsView(data,unreadIds=[]){
 const reports=(data?.reports||[]).filter(r=>['trade_created','trade_cancelled'].includes(r.event));
 return `<section class="commercial-notifications"><div class="military-section-heading"><div><span class="eyebrow">RÉSEAU COMMERCIAL</span><h2>Relations commerciales</h2></div></div>${reports.length?reports.map(r=>`<article class="commercial-notification ${unreadIds.includes(r.id)?'is-unread':''}"><div><span class="commercial-event ${r.event==='trade_created'?'created':'closed'}">${r.event==='trade_created'?'Nouvelle liaison':'Liaison fermée'}</span><h3>${h(r.planet)} <span aria-hidden="true">↔</span> ${h(r.details.other_planet)}</h3><p>${r.event==='trade_created'?'Une liaison commerciale a été activée par un autre joueur.':'L’autre joueur a fermé cette liaison commerciale.'} <span>${number(r.details.quantity)} capacités.</span></p></div><time datetime="${h(r.occurred_at)}">${date(r.occurred_at)}</time></article>`).join(''):'<p class="empty">Aucun nouveau changement commercial signalé.</p>'}</section>`;
}

export function transitView(data,pending){
 const fleets=(data?.fleets||[]).filter(f=>f.status==='transit');
 return `<div class="military-page transit-page"><div class="military-section-heading"><span>${fleets.length} flotte${fleets.length>1?'s':''} en vol</span><button class="secondary" data-page="fleets">Armées & flottes →</button></div>${pending?'<p>Un ordre attend sa confirmation dans Armées & flottes.</p>':''}${fleets.length?fleets.map(f=>{const progress=Math.max(0,Math.min(100,(Date.now()-new Date(f.departed_at))/(new Date(f.arrives_at)-new Date(f.departed_at))*100));return `<div class="transit-track"><div class="route-progress" role="progressbar" aria-label="Progression du trajet" aria-valuenow="${Math.round(progress)}" aria-valuemin="0" aria-valuemax="100"><i style="width:${progress}%"></i></div>${fleetPanel(f)}</div>`;}).join(''):'<div class="document-panel empty"><h2>Aucune flotte en transit</h2><p>Vos déplacements et changements de trajectoire apparaîtront ici.</p></div>'}<section id="mission-orders" class="mission-orders" hidden></section></div>`;
}
